"network-storage-latency:nvme-over-fabrics":{"type":"foundation","label":{"zh":"传输方式决定往返","en":"The transport sets the round trip"},"reason":{"zh":"第 7 章的三种传输，对应第 5 章延迟账里实测的不同网络往返时间。","en":"The three transports of chapter 7 correspond to the different measured fabric round trips in chapter 5's latency budget."},"source":"../computing/systems/storage-over-a-network/#ch7"},
"network-storage-latency:rdma-roce-lossless":{"type":"foundation","label":{"zh":"省下的那十几微秒","en":"The microseconds RDMA saves"},"reason":{"zh":"第 6 章的 RDMA 省掉的，正是第 5 章延迟账里 TCP 和 RDMA 往返之间相差的那十几微秒。","en":"What RDMA saves in chapter 6 is the gap of a dozen or so microseconds between the TCP and RDMA round trips in chapter 5's latency budget."},"source":"../computing/systems/storage-over-a-network/#ch6"},
"newton-method:binary-search":{"type":"connection","label":{"zh":"快但挑起点 vs 慢但稳","en":"Fast but picky vs slow but safe"},"reason":{"zh":"第 5 步在同一道开方题上比较两种求根思路：二分法每次只砍一半，牛顿法位数翻倍。","en":"Step 5 compares two root-finding ideas on one square-root problem: bisection halves the bracket, Newton doubles the digits."},"source":"../math/calculus/newton-method/#step5"},
"northbridge-southbridge:chipset-uplink":{"type":"foundation","label":{"zh":"南桥变成芯片组","en":"The southbridge becomes the chipset"},"reason":{"zh":"第 5 章的芯片组和上行链路，是第 3 章南桥和 Hub Interface 的后代。","en":"Chapter 5's chipset and uplink descend from chapter 3's southbridge and Hub Interface."},"source":"../computing/systems/how-a-computer-is-wired/#ch5"},
