"nvme-protocol-overhead:network-storage-latency":{"type":"foundation","label":{"zh":"同一笔延迟账","en":"The same latency budget"},"reason":{"zh":"第 5 章是《NVMe 为什么这么快》第 1 章的延迟拆解换到网线上：介质时间不变，多出来一段网络。","en":"Chapter 5 is chapter 1 of “Why NVMe Is So Fast” moved onto the network: the media time is the same, with a network leg added."},"source":"../computing/systems/storage-over-a-network/#ch5"},
"nvme-ring-doorbell-dma:nvme-over-fabrics":{"type":"foundation","label":{"zh":"把队列拉到网络对面","en":"Stretching the queues across the network"},"reason":{"zh":"NVMe-oF 把《NVMe 为什么这么快》第 4 章的提交队列和完成队列拉到对面，命令和完成项装进胶囊。","en":"NVMe-oF stretches the submission and completion queues of chapter 4 of “Why NVMe Is So Fast” across the network, with commands and completions carried in capsules."},"source":"../computing/systems/storage-over-a-network/#ch7"},
