"pcie-lanes-generations:pcie-tlp":{"type":"foundation","label":{"zh":"链路速率里还要扣包头","en":"Headers come out of the link rate"},"reason":{"zh":"第 3 章的有效带宽是第 2 章链路速率乘上 TLP 的载荷占比。","en":"Chapter 3's effective bandwidth is chapter 2's link rate times the TLP payload share."},"source":"../computing/systems/how-pcie-works/#ch3"},
