"pcie-pam4:pcie-flit":{"type":"foundation","label":{"zh":"眼变小，就要纠错","en":"Smaller eyes need FEC"},"reason":{"zh":"第 10 章的前向纠错是为第 9 章 PAM4 更高的误码率准备的。","en":"Chapter 10's forward error correction answers the higher error rate of chapter 9's PAM4."},"source":"../computing/systems/how-pcie-works/#ch10"},
"pcie-tlp:pcie-ack-nak":{"type":"foundation","label":{"zh":"序号和 LCRC","en":"Sequence number and LCRC"},"reason":{"zh":"第 3 章图里数据链路层加上的序号和 LCRC，第 5 章用来确认和重发。","en":"The sequence number and LCRC that the data link layer adds in chapter 3's diagram are what chapter 5 uses to acknowledge and replay."},"source":"../computing/systems/how-pcie-works/#ch5"},
